ViewName.viewListNeedBlockWaitingViewOnLoad = {
	ViewName.VirtualJoystick,
	ViewName.Login,
	ViewName.LoginSimulationSDK,
	ViewName.MainUI,
	ViewName.GMView,
	ViewName.HorseLanternView
}

function ViewName.isBlockWaitingViewOnLoad(viewName)
	local isBlock = false

	for _, v in ipairs(ViewName.viewListNeedBlockWaitingViewOnLoad) do
		if v == viewName then
			isBlock = true

			break
		end
	end

	return isBlock
end

return ViewName
